#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    long long l, r;
    cin >> a >> b >> l >> r;

    if (r - l + 1 >= 2LL * (a + b)) {
        cout << (a <= b ? a + 1 : 2 * a - b) << "\n";
        return 0;
    }

    string pattern;
    for (int i = 0; i < a; i++) {
        pattern += ('a' + i);
    }

    l--;
    r--;

    std::set<int> usedChars;
    int minDistinct = 26;

    for (int firstChar = 0; firstChar < 26; firstChar++) {
        for (int secondChar = a; secondChar < 26; secondChar++) {
            std::string currentString = pattern;
            for (int i = 0; i < b; i++) {
                currentString += ('a' + firstChar);
            }
            usedChars.clear();
            for (char c : currentString.substr((int)currentString.size() - a)) {
                usedChars.insert(c - 'a');
            }
            int nextCharIndex = 0;
            for (int i = 0; i < a; i++) {
                while (usedChars.count(nextCharIndex)) {
                    nextCharIndex++;
                }
                currentString += ('a' + nextCharIndex);
                nextCharIndex++;
            }
            for (int i = 0; i < b; i++) {
                currentString += ('a' + secondChar);
            }
            int length = (int)currentString.size();
            usedChars.clear();
            for (long long i = l % length; i != (r + 1) % length; i = (i + 1) % length) {
                usedChars.insert(currentString[(int)i] - 'a');
            }
            if ((int)usedChars.size() < minDistinct) {
                minDistinct = (int)usedChars.size();
            }
        }
    }
    cout << minDistinct << "\n";

    return 0;
}
